MAP
	NAME 'todas_las_capas'
    INCLUDE 'includes/globals.map'
	WEB
		INCLUDE "includes/temp_directory.map"
      METADATA
			 'ows_title' 'Todas las capas'
			 INCLUDE 'includes/common_metadata.map'
	    END
	END
    CONFIG "MS_ERRORFILE" "/srv/mapserver/err_tmpcapas.log"
    DEBUG 0
  ##Inicia TmpCuentas, se usa en Capas Dinamicas
  ## -Cortes y reconexiones
  ## -Predios a visitar por padron de usuarios
  ## -Adeudan en documentos
  ## -Cartera vencida
  
  ## -------------------------------------------Layers-----------------------------------------------------
  LAYER #IniciaTmpAntenas
    INCLUDE 'includes/conexion.map'
    CONNECTIONTYPE POSTGIS
    NAME "antenas_tmp"
    STATUS DEFAULT
    METADATA
			'ows_include_items' 'all'
			'gml_include_items' 'all'
    END
    PROJECTION
      'init=epsg:32614'
    END
    VALIDATION
      "clusuario" "^[0-9A-Za-z]{1,20}$"
    END
    DATA "geometry from (select a.gid, a.geometry, b.color from predios a join vw_tmpantenas b on a.gid = b.npredio join vw_usuarios u on b.sid = u.id WHERE u.nombre = '%clusuario%') as tmp using unique gid using srid=32614"
    TYPE polygon
    CLASS
      STYLE
        SYMBOL 'plainline'
        SIZE 3
        COLOR -1 -1 -1
        OUTLINECOLOR [color]
      END
    END
  END
  LAYER #Ubicacion Antenas
    CONNECTIONTYPE POSTGIS
    INCLUDE 'includes/conexion.map'
    NAME "ubicacion_antenas"
    STATUS DEFAULT
    METADATA
			'ows_include_items' 'all'
			'gml_include_items' 'all'
    END
    PROJECTION
      'init=epsg:32614'
    END
    VALIDATION
      "clusuario" "^[0-9A-Za-z]{1,20}$"
    END
    TYPE POINT
    DATA "geometry from (select b.gid, st_geomfromtext(st_astext(b.geometry), 32614) AS geometry, b.nombre from vw_tmpantenas2 b join vw_usuarios u on b.sid = u.id WHERE u.nombre = '%clusuario%')  as tmp using unique gid using srid=32614"
    LABELITEM "nombre"
    CLASS
      STYLE
        SYMBOL 'puntos'
        SIZE 12
        COLOR 254 254 254
        OUTLINECOLOR 0 0 0
      END
      LABEL
        TYPE TRUETYPE
        FONT "arial"
        OFFSET 0 15
        SIZE 13
        COLOR 0 0 0
        OUTLINECOLOR 255 255 255
      END
    END
  END
  LAYER #CortesLimitaciones 
    INCLUDE 'includes/conexion.map'
    CONNECTIONTYPE POSTGIS
    NAME "cd_cortes_y_reconexiones"
    STATUS DEFAULT
      VALIDATION
        "clusuario" "^[0-9A-Za-z]{1,20}$"
      END
      PROJECTION
        'init=epsg:32614'
      END
      METADATA
        'ows_include_items' 'all'
        'gml_include_items' 'all'
      END
    DATA "geometry from (select a.gid, a.geometry,b.etiquetar from predios a join vw_tmpcuentas b on a.gid = b.gid join vw_usuarios u on b.sid = u.id WHERE u.nombre = '%clusuario%') as tmp using unique gid using srid=32614"
    TYPE polygon
    LABELITEM "etiquetar"
    CLASS
        STYLE
          SYMBOL 'plainline'
          SIZE 3
          COLOR -1 -1 -1
          OUTLINECOLOR 0 0 255
        END
        LABEL
          TYPE TRUETYPE
          FONT ARIAL
          SIZE 15
          COLOR 0 0 255
          OUTLINECOLOR 254 254 254
        END
    END
  END
  LAYER #MedidoresColor
    INCLUDE 'includes/conexion.map'
