    DATA "geometry from (select a.gid, a.geometry, a.etapa, a.nombre from subcircuitos a join vw_tmpsectores b on a.gid = b.gid join vw_usuarios u on b.sid = u.id WHERE u.nombre = '%clusuario%') as tmp using unique gid using srid=32614"
