  LAYER #ResaltarAmarilloInstalaciones 
    CONNECTIONTYPE POSTGIS
    INCLUDE 'includes/conexion.map'
    NAME "SS_MAP_GRAL_INSTALACIONES"
    STATUS DEFAULT
    METADATA
      'ows_title' 'SS_MAP_GRAL_INSTALACIONES'
      'ows_include_items' 'all'
      'gml_include_items' 'all'
    END
    PROJECTION
      'init=epsg:32614'
    END
    VALIDATION
      "clusuario" "^[0-9A-Za-z]{1,20}$"
    END
    TYPE POINT
    DATA "geometry from (select ins.geometry, ins.gid from k_busqueda b join bn_inst_sapal ins on ins.gid = b.id_elemento_geografico where b.nb_tabla = 'bn_inst_sapal' and b.cl_usuario = '%clusuario%') as tmp using unique gid using srid=32614"
    CLASS
      TEMPLATE 'x.html'
      STYLE
        SYMBOL "puntos"
        COLOR 255 255 0
        SIZE 10
        OUTLINECOLOR 0 0 0
      END ## STYLE
    END ## CLASS
  END ## LAYER
