  LAYER#GenerarEtiquetasLecturistas
    CONNECTIONTYPE POSTGIS
    METADATA
      'ows_title' 'etiquetas lecturistas'
      'ows_include_items' 'all'
      'gml_include_items' 'all'
    END
    VALIDATION
      "clusuario" "^[0-9A-Za-z]{1,20}$"
    END
    PROJECTION
      'init=epsg:32614'
    END
    NAME "etiquetas lecturistas"
    INCLUDE 'includes/conexion.map'
    DATA "geometry from (select a.gid,a.geometry,a.etiquetar,a.color from vw_tmprutasl a join vw_usuarios u on a.sid = u.id WHERE u.nombre = '%clusuario%') as tmp using unique gid using srid=32614"
    STATUS DEFAULT
    TYPE line
    LABELITEM "etiquetar"
    CLASS
      LABEL
        TYPE TRUETYPE
        FONT "arial"
        SIZE 15
        COLOR 0 0 0
        OUTLINECOLOR 254 254 254
      END
    END
  END
